   var changed=new Trial(Path.Combine(root,"changed"),true);changed.probeAction=()=>changed.epoch++;await Reject(()=>changed.actor.CollectOneClickAsync(changed.Click()));Check(changed.calls==0&&changed.store.SeparatedRequestIds("a").Count==0,"ContextChangesDuringProbeBlocks");
